package com.gamehubstore.notification_mscv.controllers; import com.gamehubstore.notification_mscv.models.Notification; import com.gamehubstore.notification_mscv.services.NotificationService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/notifications") public class NotificationController { private final NotificationService service; public NotificationController(NotificationService s){service=s;} @GetMapping public List<Notification> all(){return service.all();} @GetMapping("/user/{id}") public List<Notification> byUser(@PathVariable Long id){return service.byUser(id);} @GetMapping("/{id}") public Notification byId(@PathVariable Long id){return service.byId(id);} @PostMapping public ResponseEntity<Notification> create(@Valid @RequestBody Notification n){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(n));} @PatchMapping("/{id}/read") public Notification markRead(@PathVariable Long id){return service.markRead(id);} @DeleteMapping("/{id}") public ResponseEntity<Void> archive(@PathVariable Long id){service.archive(id);return ResponseEntity.noContent().build();} }
